import React, { useState, useRef, useEffect } from 'react';
import './App.css';

function App() {
  const [files, setFiles] = useState([]);
  const [uploadedFiles, setUploadedFiles] = useState([]);
  const [question, setQuestion] = useState('');
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [mode, setMode] = useState('loading');
  const [totalChunks, setTotalChunks] = useState(0);
  const [uploadProgress, setUploadProgress] = useState({});
  const messagesEndRef = useRef(null);

  // Get mode on load
  useEffect(() => {
    fetch('http://localhost:8000/')
      .then(res => res.json())
      .then(data => {
        setMode(data.mode);
        setTotalChunks(data.total_chunks);
      })
      .catch(() => setMode('unknown'));
    
    // Load existing files
    loadUploadedFiles();
  }, []);

  // Auto scroll
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const loadUploadedFiles = async () => {
    try {
      const res = await fetch('http://localhost:8000/admin/health');
      const data = await res.json();
      if (data.chunks) {
        setTotalChunks(data.chunks);
      }
    } catch (err) {
      console.error('Error loading files:', err);
    }
  };

  const handleFileSelect = (e) => {
    const selectedFiles = Array.from(e.target.files);
    setFiles(prev => [...prev, ...selectedFiles]);
  };

  const removeFile = (index) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  const uploadAllFiles = async () => {
    if (files.length === 0) {
      alert('Please select files to upload');
      return;
    }

    setLoading(true);
    
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const formData = new FormData();
      formData.append('file', file);
      
      setUploadProgress(prev => ({ ...prev, [file.name]: 0 }));
      addMessage('system', `📤 Uploading ${file.name}...`);
      
      try {
        const xhr = new XMLHttpRequest();
        xhr.upload.addEventListener('progress', (e) => {
          if (e.lengthComputable) {
            const percent = (e.loaded / e.total) * 100;
            setUploadProgress(prev => ({ ...prev, [file.name]: percent }));
          }
        });
        
        const promise = new Promise((resolve, reject) => {
          xhr.onload = () => {
            if (xhr.status === 200) {
              resolve(JSON.parse(xhr.responseText));
            } else {
              reject(new Error('Upload failed'));
            }
          };
          xhr.onerror = () => reject(new Error('Network error'));
          xhr.open('POST', 'http://localhost:8000/upload');
          xhr.send(formData);
        });
        
        const data = await promise;
        addMessage('system', `✅ ${file.name}: ${data.chunks} chunks created`);
        setTotalChunks(data.total_chunks);
        setUploadedFiles(prev => [...prev, { 
          name: file.name, 
          chunks: data.chunks,
          uploadedAt: new Date().toLocaleTimeString()
        }]);
        
      } catch (err) {
        addMessage('system', `❌ Failed to upload ${file.name}`);
      }
    }
    
    setFiles([]);
    setUploadProgress({});
    setLoading(false);
    addMessage('system', `✨ All files uploaded! Total chunks: ${totalChunks}`);
  };

  const askQuestion = async () => {
    if (!question.trim()) return;
    
    const userQuestion = question;
    setQuestion('');
    addMessage('user', userQuestion);
    setLoading(true);
    
    try {
      const res = await fetch(`http://localhost:8000/ask?question=${encodeURIComponent(userQuestion)}`, {
        method: 'POST'
      });
      const data = await res.json();
      
      if (data.error) {
        addMessage('bot', `❌ ${data.error}`);
      } else {
        addMessage('bot', data.answer);
        addMessage('system', `📚 Found ${data.sources} relevant sections from ${data.total_chunks} total chunks`);
        setTotalChunks(data.total_chunks);
      }
    } catch (err) {
      addMessage('bot', '❌ Error getting answer. Make sure backend is running.');
    }
    setLoading(false);
  };

  const addMessage = (role, content) => {
    setMessages(prev => [...prev, { role, content, id: Date.now() }]);
  };

  const clearChat = () => {
    setMessages([]);
  };

  const clearAllData = async () => {
    if (confirm('⚠️ This will delete ALL uploaded documents and training data. Are you sure?')) {
      try {
        await fetch('http://localhost:8000/training/clear', { method: 'DELETE' });
        setTotalChunks(0);
        setUploadedFiles([]);
        addMessage('system', '🗑️ All data cleared!');
      } catch (err) {
        addMessage('system', '❌ Failed to clear data');
      }
    }
  };

  return (
    <div className="app">
      <header>
        <h1>🤖 RAG Chatbot</h1>
        <div className="header-info">
          <div className="mode-badge">
            {mode === 'EXE' ? '💻 Desktop Mode' : mode === 'HOSTED' ? '☁️ Cloud Mode' : '🔄 Loading...'}
          </div>
          <div className="chunks-badge">📊 {totalChunks} chunks</div>
        </div>
      </header>

      {/* Upload Section - Multiple Files */}
      <div className="upload-section">
        <div className="upload-header">
          <h3>📄 Upload Documents</h3>
          <p>Select multiple PDF files to train the chatbot</p>
        </div>
        
        <div className="upload-area">
          <input 
            type="file" 
            accept=".pdf" 
            onChange={handleFileSelect}
            multiple
            id="file-input"
            hidden
          />
          <label htmlFor="file-input" className="upload-label">
            📁 Click or Drag to Select PDFs
          </label>
          
          {files.length > 0 && (
            <div className="file-list">
              <h4>Selected Files ({files.length})</h4>
              {files.map((file, idx) => (
                <div key={idx} className="file-item">
                  <div className="file-info">
                    <span className="file-icon">📄</span>
                    <span className="file-name">{file.name}</span>
                    <span className="file-size">({(file.size / 1024).toFixed(0)} KB)</span>
                  </div>
                  {uploadProgress[file.name] && (
                    <div className="progress-bar">
                      <div style={{ width: `${uploadProgress[file.name]}%` }}></div>
                    </div>
                  )}
                  <button className="remove-file" onClick={() => removeFile(idx)}>✖</button>
                </div>
              ))}
              <div className="upload-actions">
                <button onClick={uploadAllFiles} disabled={loading}>
                  {loading ? 'Uploading...' : `📤 Upload All (${files.length} files)`}
                </button>
                <button onClick={() => setFiles([])} disabled={loading}>Clear All</button>
              </div>
            </div>
          )}
        </div>
        
        {/* Uploaded Documents List */}
        {uploadedFiles.length > 0 && (
          <div className="uploaded-list">
            <h4>📚 Uploaded Documents ({uploadedFiles.length})</h4>
            <div className="uploaded-items">
              {uploadedFiles.map((file, idx) => (
                <div key={idx} className="uploaded-item">
                  <span className="file-icon">✅</span>
                  <span className="file-name">{file.name}</span>
                  <span className="file-chunks">{file.chunks} chunks</span>
                  <span className="file-time">{file.uploadedAt}</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Chat Section */}
      <div className="chat-section">
        <div className="chat-header">
          <h3>💬 Chat with Documents</h3>
          <div className="chat-actions">
            <button onClick={clearChat} className="icon-btn" title="Clear Chat">🗑️</button>
            <button onClick={clearAllData} className="icon-btn danger" title="Delete All Data">⚠️</button>
          </div>
        </div>
        
        <div className="messages-container">
          {messages.length === 0 ? (
            <div className="welcome">
              <h3>Welcome! 👋</h3>
              <p>1. Upload one or more PDF documents</p>
              <p>2. Ask questions about the content</p>
              <p>3. Get instant AI answers!</p>
              <div className="example-questions">
                <h4>Try asking:</h4>
                <button onClick={() => setQuestion("What is this document about?")}>
                  What is this document about?
                </button>
                <button onClick={() => setQuestion("Give me a summary")}>
                  Give me a summary
                </button>
                <button onClick={() => setQuestion("List all important points")}>
                  List all important points
                </button>
              </div>
            </div>
          ) : (
            messages.map((msg) => (
              <div key={msg.id} className={`message ${msg.role}`}>
                <div className="avatar">
                  {msg.role === 'user' ? '👤' : msg.role === 'bot' ? '🤖' : 'ℹ️'}
                </div>
                <div className="content">
                  {msg.content}
                </div>
              </div>
            ))
          )}
          {loading && (
            <div className="typing">
              <span>🤖</span>
              <span>Thinking</span>
              <span>.</span><span>.</span><span>.</span>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        <div className="input-area">
          <textarea
            value={question}
            onChange={(e) => setQuestion(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && !e.shiftKey && askQuestion()}
            placeholder="Ask anything about your documents..."
            rows="2"
          />
          <button onClick={askQuestion} disabled={loading || totalChunks === 0}>
            Send 📨
          </button>
        </div>
      </div>
    </div>
  );
}

export default App;
